using System.Security.Cryptography; using System.Text.Json; using InovaGed.Application.Continuity;
namespace InovaGed.Infrastructure.Continuity;
public sealed class PortabilityPackageVerifier:IPortabilityPackageVerifier { public async Task<PortabilityVerificationResult> VerifyAsync(string packagePath,CancellationToken ct){if(!Directory.Exists(packagePath))return new(false,["Pacote não encontrado."]);var path=Path.Combine(packagePath,"manifest.json");if(!File.Exists(path))return new(false,["manifest.json ausente."]);var findings=new List<string>();PortabilityManifest? manifest;try{manifest=JsonSerializer.Deserialize<PortabilityManifest>(await File.ReadAllTextAsync(path,ct));}catch(JsonException){return new(false,["Manifesto inválido."]);}if(manifest is null)return new(false,["Manifesto inválido."]);foreach(var file in manifest.Files){var full=Path.GetFullPath(Path.Combine(packagePath,file.Path));if(!full.StartsWith(Path.GetFullPath(packagePath)+Path.DirectorySeparatorChar,StringComparison.Ordinal)){findings.Add("Path traversal no manifesto.");continue;}if(!File.Exists(full)){findings.Add("Arquivo ausente: "+file.Path);continue;}await using var stream=File.OpenRead(full);var hash=Convert.ToHexString(await SHA256.HashDataAsync(stream,ct)).ToLowerInvariant();if(!string.Equals(hash,file.Sha256,StringComparison.OrdinalIgnoreCase))findings.Add("Checksum divergente: "+file.Path);}return new(findings.Count==0,findings);} }
